        [InlineData("013", "wiiu", ".nkds", "ds", "iso", "datLookup", false, false, false, "iso", "image", "Convert-Image(M,V:NoVerify,C:ScanStep)")]
        [InlineData("014", "wiiu", ".nkds", "ds", "iso", "datLookup", false, true, false, "iso", "image", "Convert-Image(M,V:DatLookup [Md5+Crc32],C:ScanStep)")]
        [InlineData("015", "wiiu", ".nkds", "ds", "iso", "datLookup", false, true, true, "iso", "image", "Convert-Image(M,V:DatLookup [Md5+Crc32],C:ScanStep)")]
        [InlineData("016", "wiiu", ".nkds", "ds", "iso", "datLookup", true, false, false, "iso", "image", "Convert-Image(M,V:NoVerify,C:ScanStep)")]
        [InlineData("017", "wiiu", ".nkds", "ds", "iso", "datLookup", true, true, false, "iso", "image", "Convert-Image(M,V:DatLookup [Md5+Crc32],C:ScanStep)")]
        [InlineData("018", "wiiu", ".nkds", "ds", "iso", "datLookup", true, true, true, "iso", "image", "Convert-Image(M,V:DatLookup [Md5+Crc32],C:ScanStep)")]
        public void ConvertWiiu_NkdsIso(string idx, string system, string srcFormat, string srcInfo, string convert, string prmV, bool inScan, bool dats, bool datItem, string cfg, string outType, string resultString) => convertTest(system, srcFormat, srcInfo, convert, prmV, inScan, dats, datItem, cfg, outType, resultString);
        #endregion

        private void convertTest(string system, string srcFormat, string srcInfo, string convert, string prmV, bool inScan, bool dats, bool datItem, string cfg, string outType, string resultString)
        {
            string taskType = "convert";
            // ReqPatch is only set by the WiiGc reader for the Expand task.
            // Convert reads the corrected nkit image in a single pass, so ReqPatch is never set.
            bool reqPatch = false;
            bool nkitHeader = srcInfo.Contains("nkit");
            bool isIdx = srcInfo.Contains("idx");
            bool srcCrcHash = nkitHeader;

            IParts parts = TaskStepsShared.CreateInChecksums(srcFormat, nkitHeader);

            NKitTaskContext task = TaskStepsShared.Process(taskType, system, srcFormat, srcInfo, convert, reqPatch, prmV, parts, inScan, dats, datItem, cfg);
            TaskStepResult[] results = TaskStepsShared.GetResults(resultString);
            int i = 0;

            Assert.Equal(results.Length, task.Steps.Count);
            Assert.Equal(1, results.Count(a => a.IsMain));
            foreach (NKitStepContext step in task.Steps)
            {
                NKitVerify.RequiredChecksums(dats, parts, step.StepInfo, out string chkString);
                Assert.Equal(results[i].Name, step.StepInfo.Name);
                if (step.StepInfo.Name != "NotSet-NotSupported")
                {
                    if (results[i].IsMain)
                    {
                        Assert.Equal(cfg.ToLower(), step.StepInfo.ImageConfig.ToLower());
                        if (step.StepInfo.WriteImage)
                            Assert.Equal(outType.ToLower(), step.StepInfo.OutputType.ToString().ToLower());
                    }
                    if (results[i].IsVerify)
                        Assert.Equal(results[i].VerifyType, chkString);
                    Assert.Equal(results[i].ClassName, step.Step.GetType().Name);
                }
                i++;
            }
        }
    }
}